import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const Avaliacao = () => {
  const { id } = useParams();
  const [avaliacoesDisponiveis, setAvaliacoesDisponiveis] = useState([]);
  const [avaliacoesSubmetidas, setAvaliacoesSubmetidas] = useState([]);

  useEffect(() => {
    const fetchAvaliacoes = async () => {
      // Avaliações disponíveis
      const disponiveis = await private_api.get(`/aluno/${id}/avaliacoes`);
      if (disponiveis.status === 200) {
        setAvaliacoesDisponiveis(disponiveis.data);
      }

      // Avaliações já submetidas
      const submetidas = await private_api.get(
        `/aluno/${id}/avaliacoes/submetidas`
      );
      if (submetidas.status === 200) {
        setAvaliacoesSubmetidas(submetidas.data);
      }
    };
    fetchAvaliacoes();
  }, [id]);

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href="#">
          Cursos
        </a>
        <a className="nav-link" href="#">
          Aulas
        </a>
        <a className="nav-link active" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Avaliações</h2>

      {/* Avaliações disponíveis */}
      <div className="bg-white p-3 rounded shadow w-75">
        <h4>Faça uma avaliação</h4>
        {avaliacoesDisponiveis.length > 0 ? (
          <div>
            <p>Selecione uma avaliação para realizar:</p>
            <ul className="list-group">
              {avaliacoesDisponiveis.map((avaliacao) => (
                <li
                  key={avaliacao.id}
                  className="list-group-item d-flex justify-content-between align-items-center"
                >
                  {avaliacao.titulo}
                  <button className="btn btn-primary btn-sm">Realizar</button>
                </li>
              ))}
            </ul>
          </div>
        ) : (
          <p>No momento, não há avaliações disponíveis para você fazer.</p>
        )}
      </div>

      {/* Avaliações submetidas */}
      <div className="bg-white p-3 rounded shadow mt-4 w-75">
        <h4>Avaliações enviadas</h4>
        {avaliacoesSubmetidas.length > 0 ? (
          <div>
            <p>Você concluiu as avaliações listadas abaixo.</p>
            <table className="table table-bordered mt-3">
              <thead>
                <tr>
                  <th>Título</th>
                  <th>Pontuação registrada</th>
                  <th>Tempo</th>
                  <th>Entregue</th>
                </tr>
              </thead>
              <tbody>
                {avaliacoesSubmetidas.map((avaliacao, index) => (
                  <tr key={index}>
                    <td>{avaliacao.titulo}</td>
                    <td>
                      {avaliacao.pontuacao}/{avaliacao.pontuacaoMaxima}
                    </td>
                    <td>{avaliacao.tempo}</td>
                    <td>
                      {new Date(avaliacao.dataSubmissao).toLocaleString()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <p>Você ainda não submeteu nenhuma avaliação.</p>
        )}
      </div>
    </div>
  );
};

export default Avaliacao;
